raw_shacl_shapes:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix agt: <http://mnemosyne.dev/agent#> .
@prefix wf: <http://mnemosyne.dev/workflow#> .

agt:RunSessionIriShape a sh:NodeShape ;
    sh:targetClass agt:Session ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WS1: agt:Session IRI must be urn:sophia:agent:{agentId}:session:{sessionId}." ;
        sh:select """
            PREFIX agt: <http://mnemosyne.dev/agent#>
            SELECT $this WHERE {
              $this agt:ofAgent ?agent ; agt:sessionId ?sessionId .
              ?agent agt:agentId ?agentId .
              FILTER(STR($this) != CONCAT('urn:sophia:agent:', ?agentId, ':session:', ?sessionId))
            }
        """ ;
    ] .

agt:RunIriShape a sh:NodeShape ;
    sh:targetClass agt:Run ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WS1: agt:Run IRI must be {ofSessionIri}:run:{runId}." ;
        sh:select """
            PREFIX agt: <http://mnemosyne.dev/agent#>
            SELECT $this WHERE {
              $this agt:ofSession ?session ; agt:runId ?runId .
              FILTER(STR($this) != CONCAT(STR(?session), ':run:', STR(?runId)))
            }
        """ ;
    ] .

agt:RunRealizationShape a sh:NodeShape ;
    sh:targetClass agt:Run ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WS1: agt:Run must agt:realizedBy a wf:Run." ;
        sh:select """
            PREFIX agt: <http://mnemosyne.dev/agent#>
            PREFIX wf: <http://mnemosyne.dev/workflow#>
            SELECT $this WHERE {
              $this a agt:Run .
              FILTER NOT EXISTS { $this agt:realizedBy ?run . ?run a wf:Run . }
            }
        """ ;
    ] .

agt:RunTurnIriShape a sh:NodeShape ;
    sh:targetClass agt:Turn ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WS1: node-grain agt:Turn IRI must be {runIri}:turn:{ordinal}." ;
        sh:select """
            PREFIX agt: <http://mnemosyne.dev/agent#>
            SELECT $this WHERE {
              $this agt:inRun ?run ; agt:ordinal ?ordinal .
              FILTER(STR($this) != CONCAT(STR(?run), ':turn:', STR(?ordinal)))
            }
        """ ;
    ] .

agt:RunTurnRealizationShape a sh:NodeShape ;
    sh:targetClass agt:Turn ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WF-3b: agt:Turn must agt:realizedBy a wf:AgentRun." ;
        sh:select """
            PREFIX agt: <http://mnemosyne.dev/agent#>
            PREFIX wf: <http://mnemosyne.dev/workflow#>
            SELECT $this WHERE {
              $this a agt:Turn .
              FILTER NOT EXISTS { $this agt:realizedBy ?agentRun . ?agentRun a wf:AgentRun . }
            }
        """ ;
    ] .

agt:RunTurnGrainShape a sh:NodeShape ;
    sh:targetClass agt:Turn ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WF-3b: agt:Turn agt:turnGrain must be either node or message." ;
        sh:select """
            PREFIX agt: <http://mnemosyne.dev/agent#>
            SELECT $this WHERE {
              $this a agt:Turn .
              FILTER NOT EXISTS { $this agt:turnGrain ?grain . FILTER(?grain = 'node' || ?grain = 'message') }
            }
        """ ;
    ] .

agt:ProjectionIdentityUnificationShape a sh:NodeShape ;
    sh:targetClass agt:Agent ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WF-3b: agt:Agent subject IRI must equal urn:sophia:agent:{agentId}." ;
        sh:select """
            PREFIX agt: <http://mnemosyne.dev/agent#>
            SELECT $this WHERE {
              $this agt:agentId ?id .
              FILTER(STR($this) != CONCAT('urn:sophia:agent:', ?id))
            }
        """ ;
    ] .

agt:ProjectionMonovocalCardinalityShape a sh:NodeShape ;
    sh:targetClass agt:Agent ;
    sh:sparql [
        sh:severity sh:Violation ;
        sh:message "WF-3b: a Monovocal projected agent must have exactly one agt:Voice." ;
        sh:select """
            PREFIX agt: <http://mnemosyne.dev/agent#>
            SELECT $this WHERE {
              $this agt:voicing agt:Monovocal .
              { SELECT $this (COUNT(?v) AS ?n) WHERE { ?v agt:voiceOf $this } GROUP BY $this }
              FILTER(?n != 1)
            }
        """ ;
    ] .
